def transform(g):
    H,W=len(g),len(g[0])
    cnt=collections.Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    sep=None
    for i in range(H):
        if len(set(g[i]))==1 and g[i][0]!=bg: sep=g[i][0]; break
    if sep is None:
        for j in range(W):
            col={g[i][j] for i in range(H)}
            if len(col)==1 and next(iter(col))!=bg: sep=next(iter(col)); break
    rsep=[i for i in range(H) if all(x==sep for x in g[i])]
    csep=[j for j in range(W) if all(g[i][j]==sep for i in range(H))]
    rb=[i for i in range(H) if i not in rsep]
    cb=[j for j in range(W) if j not in csep]
    def runs(idx):
        out=[];cur=[idx[0]]
        for a in idx[1:]:
            if a==cur[-1]+1: cur.append(a)
            else: out.append(cur);cur=[a]
        out.append(cur);return out
    R,C=runs(rb),runs(cb)
    blocksGrid={}
    for bi,rw in enumerate(R):
        for bj,cl in enumerate(C):
            b=[[g[i][j] for j in cl] for i in rw]
            has=any(x!=bg for r_ in b for x in r_)
            blocksGrid[(bi,bj)]=(b,has)
    from collections import defaultdict
    byshape=defaultdict(list)
    for k,(b,has) in blocksGrid.items(): byshape[(len(b),len(b[0]))].append(k)
    out=[r[:] for r in g]
    for shape,ks in byshape.items():
        srcs=[k for k in ks if blocksGrid[k][1]]
        if len(srcs)==1:
            src=blocksGrid[srcs[0]][0]
            for k in ks:
                if k!=srcs[0]:
                    rw,cl=R[k[0]],C[k[1]]
                    for i in range(shape[0]):
                        for j in range(shape[1]):
                            out[rw[i]][cl[j]]=src[i][j]
    return out

